import{_ as e,o as a,c as d,a3 as o}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"配置参考","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"配置参考 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/guide/configuration"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/guide/configuration"}]]},"headers":[],"relativePath":"zh/catter/guide/configuration.md","filePath":"zh/catter/guide/configuration.md","lastUpdated":1793027483000}'),c={name:"zh/catter/guide/configuration.md"};function r(n,t,i,l,h,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="配置参考" tabindex="-1">配置参考 <a class="header-anchor" href="#配置参考" aria-label="Permalink to &quot;配置参考&quot;">​</a></h1><h2 id="catter-命令行" tabindex="-1">catter 命令行 <a class="header-anchor" href="#catter-命令行" aria-label="Permalink to &quot;catter 命令行&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter &lt;command&gt; [options] -- &lt;build-command&gt;</span></span></code></pre></div><p>每次运行都要指定一个命令，选项写在命令之后。<code>catter --help</code> 列出所有命令，<code>catter &lt;command&gt; --help</code> 显示某个命令的选项。不指定命令时，catter 列出所有命令并报错退出。</p><h3 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>compile-commands</code></td><td>根据捕获的编译器命令生成 <code>compile_commands.json</code> 文件。见<a href="./../features/compilation-database">编译数据库</a>。</td></tr><tr><td><code>tree</code></td><td>把捕获的命令渲染为命令树。见<a href="./../features/command-tree">命令树</a>。</td></tr><tr><td><code>targets</code></td><td>把捕获的构建目标渲染为扁平的目标森林。见<a href="./../features/target-tree">目标树</a>。</td></tr><tr><td><code>explain</code></td><td>打印 catter 如何分析 <code>--</code> 之后的命令，而不运行它。见<a href="./../features/explain">命令分析</a>。</td></tr><tr><td><code>run</code></td><td>只用 handler 运行构建，由它们对构建的命令做决定或观察它们。见 <a href="./../scripting/handlers">Handler</a>。</td></tr></tbody></table><p><code>compile-commands</code>、<code>tree</code> 和 <code>targets</code> 各自在构建上运行一个内置功能，命令行指定的 <a href="./../scripting/handlers">handler</a>（如果有的话）与它一起运行。<code>run</code> 只运行 handler，至少要指定一个。</p><h3 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to &quot;选项&quot;">​</a></h3><p><code>compile-commands</code>、<code>tree</code>、<code>targets</code> 和 <code>run</code> 除了各自的选项，还接受以下选项：</p><table tabindex="0"><thead><tr><th>选项</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>-C, --directory &lt;path&gt;</code></td><td>命令运行所在的目录。</td><td>当前目录</td></tr><tr><td><code>--from &lt;file&gt;</code></td><td>回放该文件中录制的构建，而不运行构建。</td><td></td></tr><tr><td><code>--handler &lt;command&gt;</code></td><td>启动一个 handler，它经自己的 stdin 和 stdout 对构建的命令做决定或观察它们；可多次指定。</td><td></td></tr><tr><td><code>--connect &lt;host:port&gt;</code></td><td>连接在该地址监听的 handler，未指定 <code>--allow-remote</code> 时只限本机；可多次指定。</td><td></td></tr><tr><td><code>--allow-remote</code></td><td>允许 <code>--connect</code> 连接其他机器上的 handler。</td><td></td></tr><tr><td><code>--handler-timeout &lt;seconds&gt;</code></td><td>catter 等待 handler 应答、以及会话结束后等待它退出的时长；<code>0</code> 表示一直等下去。</td><td><code>60</code></td></tr></tbody></table><p><code>--from</code> 代替 <code>--</code> 之后的构建命令：一次运行只能给出两者之一。相对路径从 <code>-C</code> 指定的目录算起。</p><p><code>explain</code> 也接受 <code>-C</code>，要分析的命令写在 <code>--</code> 之后。</p><h3 id="退出状态" tabindex="-1">退出状态 <a class="header-anchor" href="#退出状态" aria-label="Permalink to &quot;退出状态&quot;">​</a></h3><p>catter 像构建那样结束：以构建的退出码退出；构建被信号结束时，catter 也以同一个信号结束。重放的构建以其文件记录的退出码结束。catter 自身失败时，比如命令行有误、handler 中止了构建或编译数据库无法写入，catter 打印原因并以 1 退出。</p><p>停止 catter 就会停止构建：发给 catter 的 SIGTERM、SIGINT 或 SIGHUP 会转给构建命令，构建命令像直接收到它一样结束，catter 随后像构建那样结束。catter 被杀死时，构建命令随之结束。</p><h3 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h3><p>catter 把日志和每个运行中会话的套接字放在 <code>$HOME/.catter</code>（Linux、macOS）或 <code>%LOCALAPPDATA%\\catter</code>（Windows）。设置了环境变量 <code>CATTER_HOME</code> 时，改用它指定的目录（须为绝对路径）。</p><h2 id="catter-proxy-命令行" tabindex="-1">catter-proxy 命令行 <a class="header-anchor" href="#catter-proxy-命令行" aria-label="Permalink to &quot;catter-proxy 命令行&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>catter-proxy</code> 是内部组件，由 catter 自动调用，不需要用户直接使用。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter-proxy [options] -- &lt;command&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><code>-p &lt;id&gt;</code></td><td>用于 IPC 会话的父进程 ID</td></tr><tr><td><code>&lt;executable&gt;</code></td><td>已解析的可执行文件路径</td></tr></tbody></table><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>以下环境变量由 catter 在运行时自动设置，此处仅作参考，无需手动配置。</p><h3 id="unix-linux-macos" tabindex="-1">Unix（Linux / macOS） <a class="header-anchor" href="#unix-linux-macos" aria-label="Permalink to &quot;Unix（Linux / macOS）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>__key_catter_proxy_path_v1</code></td><td><code>catter-proxy</code> 可执行文件的路径</td></tr><tr><td><code>__key_catter_command_id_v1</code></td><td>IPC 命令标识符</td></tr><tr><td><code>LD_PRELOAD</code>（Linux）</td><td>注入 catter 钩子共享库</td></tr><tr><td><code>DYLD_INSERT_LIBRARIES</code>（macOS）</td><td>注入 catter 钩子共享库</td></tr></tbody></table><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>CATTER_IPC_ID</code></td><td>IPC 会话标识符</td></tr><tr><td><code>CATTER_PROXY_PATH</code></td><td><code>catter-proxy</code> 可执行文件的路径</td></tr></tbody></table>',27)])])}const m=e(c,[["render",r]]);export{u as __pageData,m as default};
